from typing import List
import math

def rescale_to_unit(numbers: List[float]) -> List[float]:
    min_num = min(numbers)
    max_num = max(numbers)
    range_ = max_num - min_num

    if range_ == 0:
        return [0.0] * len(numbers)

    def rescale(num):
        return (num - min_num) / range_

    return [rescale(num) for num in numbers]
