def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def next_fibonacci(num):
        if num == 0:
            return 1
        elif num == 1:
            return 1
        else:
            return next_fibonacci(num - 1) + next_fibonacci(num - 2)

    def find_fibonacci_with_prime(n):
        a, b = 0, 1
        count = 0
        while True:
            if is_prime(a):
                count += 1
                if count == n:
                    return a
            a, b = b, a + b

    return find_fibonacci_with_prime(n)

